#ifndef DFN_TEST_SUPPORT_REFERENCE_H_
#define DFN_TEST_SUPPORT_REFERENCE_H_

// Helpers to load the numerical reference data generated by
// test/support/generate_reference.py and to report comparison metrics.

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <complex>
#include <cstddef>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

namespace dfn::test {

inline std::string data_dir() {
#ifdef DFN_TEST_DATA_DIR
    return DFN_TEST_DATA_DIR;
#else
    return std::string();
#endif
}

inline bool reference_available() {
    if (data_dir().empty()) {
        return false;
    }
    std::ifstream probe(data_dir() + "/window_960.f32", std::ios::binary);
    return probe.good();
}

inline std::vector<int> load_shape_in(const std::string& dir, const std::string& name) {
    std::vector<int> shape;
    std::ifstream file(dir + "/" + name + ".shape");
    int dimension = 0;
    while (file >> dimension) {
        shape.push_back(dimension);
    }
    return shape;
}

inline std::vector<float> load_f32_in(const std::string& dir, const std::string& name) {
    std::ifstream file(dir + "/" + name + ".f32", std::ios::binary | std::ios::ate);
    if (!file.good()) {
        return {};
    }
    const std::streamsize bytes = file.tellg();
    file.seekg(0, std::ios::beg);
    std::vector<float> data(static_cast<std::size_t>(bytes) / sizeof(float));
    file.read(reinterpret_cast<char*>(data.data()), bytes);
    return data;
}

inline std::vector<std::complex<float>> load_complex_in(const std::string& dir,
                                                        const std::string& name) {
    const std::vector<float> raw = load_f32_in(dir, name);
    std::vector<std::complex<float>> data(raw.size() / 2);
    for (std::size_t i = 0; i < data.size(); ++i) {
        data[i] = std::complex<float>(raw[2 * i], raw[2 * i + 1]);
    }
    return data;
}

struct Metrics {
    float max_abs = 0.0f;
    float mean_abs = 0.0f;
    float rmse = 0.0f;
    float max_rel = 0.0f;
};

inline Metrics compute_metrics(const float* expected, const float* actual, std::size_t count) {
    Metrics metrics;
    if (count == 0) {
        return metrics;
    }
    double sum_abs = 0.0;
    double sum_sq = 0.0;
    for (std::size_t i = 0; i < count; ++i) {
        const double diff = static_cast<double>(actual[i]) - static_cast<double>(expected[i]);
        const double abs_diff = std::abs(diff);
        metrics.max_abs = std::max(metrics.max_abs, static_cast<float>(abs_diff));
        sum_abs += abs_diff;
        sum_sq += diff * diff;
        const double denom = std::max(std::abs(static_cast<double>(expected[i])), 1e-12);
        metrics.max_rel = std::max(metrics.max_rel, static_cast<float>(abs_diff / denom));
    }
    metrics.mean_abs = static_cast<float>(sum_abs / static_cast<double>(count));
    metrics.rmse = static_cast<float>(std::sqrt(sum_sq / static_cast<double>(count)));
    return metrics;
}

inline Metrics compute_metrics(const std::complex<float>* expected,
                               const std::complex<float>* actual, std::size_t count) {
    Metrics metrics;
    if (count == 0) {
        return metrics;
    }
    double sum_abs = 0.0;
    double sum_sq = 0.0;
    for (std::size_t i = 0; i < count; ++i) {
        const double diff = std::abs(actual[i] - expected[i]);
        metrics.max_abs = std::max(metrics.max_abs, static_cast<float>(diff));
        sum_abs += diff;
        sum_sq += diff * diff;
        const double denom = std::max(static_cast<double>(std::abs(expected[i])), 1e-12);
        metrics.max_rel = std::max(metrics.max_rel, static_cast<float>(diff / denom));
    }
    metrics.mean_abs = static_cast<float>(sum_abs / static_cast<double>(count));
    metrics.rmse = static_cast<float>(std::sqrt(sum_sq / static_cast<double>(count)));
    return metrics;
}

inline void report(const std::string& name, const Metrics& metrics) {
    std::cout << "[numerics] " << name << ": max_abs=" << metrics.max_abs
              << " mean_abs=" << metrics.mean_abs << " rmse=" << metrics.rmse
              << " max_rel=" << metrics.max_rel << std::endl;
}

// Reports the metrics and asserts the maximum absolute deviation.
inline void expect_max_abs(const std::string& name, const Metrics& metrics, float atol) {
    report(name, metrics);
    EXPECT_LE(metrics.max_abs, atol) << "max absolute error too large for " << name;
}

// Convenience wrappers using the default reference directory.
inline std::vector<int> load_shape(const std::string& name) {
    return load_shape_in(data_dir(), name);
}
inline std::vector<float> load_f32(const std::string& name) {
    return load_f32_in(data_dir(), name);
}
inline std::vector<std::complex<float>> load_complex(const std::string& name) {
    return load_complex_in(data_dir(), name);
}

}  // namespace dfn::test

#endif  // DFN_TEST_SUPPORT_REFERENCE_H_